15	    case 'ArrowRight':
16	      return column === size - 1 ? index : index + 1;
17	    case 'ArrowUp':
18	      return row === 0 ? index : index - size;
19	    case 'ArrowDown':
20	      return row === size - 1 ? index : index + size;
21	  }
